   135|  if (!secret || !expectedWorkerId) throw new InternalDeployAuthError('Internal worker authentication is not configured.', 401);
   136|
   137|  const workerId = trimmed(request.headers.get('X-IVX-Worker-ID'));
   138|  const timestamp = trimmed(request.headers.get('X-IVX-Timestamp'));
   139|  const nonce = trimmed(request.headers.get('X-IVX-Nonce'));
   140|  const receivedSignature = trimmed(request.headers.get('X-IVX-Deploy-Signature'));
   141|  if (!workerId || !timestamp || !nonce || !receivedSignature) throw new InternalDeployAuthError('Required signed worker authentication headers are missing.', 401);
