   143|  const timestampMs = Number(timestamp) * 1000;
   144|  if (!Number.isFinite(timestampMs) || Math.abs(Date.now() - timestampMs) > MAX_CLOCK_SKEW_MS) throw new InternalDeployAuthError('Worker request timestamp is expired or invalid.', 401);
